-- Public reference data only. No historical FreightJob/issued snapshots are rewritten.
CREATE TABLE IF NOT EXISTS "ShippingPort" (
 code TEXT PRIMARY KEY, country TEXT NOT NULL, name TEXT NOT NULL,
 "asciiName" TEXT NOT NULL, subdivision TEXT NOT NULL, functions TEXT NOT NULL,
 status TEXT NOT NULL, iata TEXT NOT NULL, coordinates TEXT NOT NULL,
 "sourceVersion" TEXT NOT NULL,
 CONSTRAINT "ShippingPort_code_check" CHECK (code ~ '^[A-Z]{2}[A-Z0-9]{3}$' AND country=left(code,2) AND left(functions,1)='1')
);
CREATE INDEX IF NOT EXISTS "ShippingPort_country_idx" ON "ShippingPort"(country,code);
ALTER TABLE "FreightJob" ADD COLUMN IF NOT EXISTS "originPortCode" TEXT;
ALTER TABLE "FreightJob" ADD COLUMN IF NOT EXISTS "destinationPortCode" TEXT;
DO $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='ShippingPort_code_check') THEN ALTER TABLE "ShippingPort" ADD CONSTRAINT "ShippingPort_code_check" CHECK (code ~ '^[A-Z]{2}[A-Z0-9]{3}$' AND country=left(code,2) AND left(functions,1)='1'); END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='FreightJob_origin_port_fkey') THEN ALTER TABLE "FreightJob" ADD CONSTRAINT "FreightJob_origin_port_fkey" FOREIGN KEY("originPortCode") REFERENCES "ShippingPort"(code) ON DELETE RESTRICT; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='FreightJob_destination_port_fkey') THEN ALTER TABLE "FreightJob" ADD CONSTRAINT "FreightJob_destination_port_fkey" FOREIGN KEY("destinationPortCode") REFERENCES "ShippingPort"(code) ON DELETE RESTRICT; END IF;
END $$;
CREATE OR REPLACE FUNCTION baro_shipping_port_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 NEW."originPortCode":=NULLIF(NEW.data->>'originPortCode','');
 NEW."destinationPortCode":=NULLIF(NEW.data->>'destinationPortCode','');
 IF (NEW."originPortCode" IS NOT NULL OR NEW."destinationPortCode" IS NOT NULL) AND NEW.mode<>'SEA' THEN RAISE EXCEPTION 'SHIPPING_PORT_MODE'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS "FreightJob_port_guard" ON "FreightJob";
CREATE TRIGGER "FreightJob_port_guard" BEFORE INSERT OR UPDATE ON "FreightJob" FOR EACH ROW EXECUTE FUNCTION baro_shipping_port_guard();

CREATE OR REPLACE FUNCTION baro_shipping_keys() RETURNS TEXT[] LANGUAGE SQL IMMUTABLE AS $$
 SELECT ARRAY['origin','destination','etd','eta','plannedDate','vessel','voyage','shipmentType','incoterms','incotermsPlace','pickupAddress','shipper','consignee','notify','cargo','marks','quantity','unit','weightKg','cbm','containerType','containerCount','dangerousGoodsDetails','deliveryDate','recipient','pickupRequired','dangerousGoods','workScope','transportService','customerRole','notifySameAsConsignee','shipperParty','consigneeParty','notifyParty','cargoSchemaVersion','containers','packages','outOfGauge','oogDetails','hsCode','dgClass','unNumber','originPortCode','destinationPortCode'];
$$;
CREATE OR REPLACE FUNCTION baro_shipping_projection(mode TEXT,status TEXT,data JSONB) RETURNS JSONB LANGUAGE SQL IMMUTABLE AS $$
 SELECT jsonb_build_object('mode',mode,'status',status,'data',COALESCE((SELECT jsonb_object_agg(key,
 CASE WHEN key IN ('shipperParty','consigneeParty','notifyParty') THEN (SELECT jsonb_object_agg(p.key,p.value) FROM jsonb_each(value) p WHERE p.key IN ('name','address','contactName','phone','email')) ELSE value END)
 FROM jsonb_each(data) WHERE key=ANY(baro_shipping_keys()) AND (data->'cargoSchemaVersion'='1'::jsonb OR key NOT IN ('shipperParty','consigneeParty','notifyParty','hsCode','dgClass','unNumber','originPortCode','destinationPortCode'))),'{}'::jsonb));
$$;

